    setResult({ state: manual ? "needs_review" : "completed", case: outcome, evidence: manual ? [...baseEvidence.slice(0, 1), conflict, ...baseEvidence.slice(1)] : name === "revised" ? [...baseEvidence.slice(0, 1), conflict, ...baseEvidence.slice(1)] : baseEvidence, warnings: outcome.warnings });
