      {result.state === "needs_review" && <div className="review-explainer"><strong>Do not treat this as a zero-overcharge result.</strong><span>The amendment is ₹525 per unit while the purchase order remains ₹480. A reviewer must resolve which price applies.</span></div>}
      <div className="metric-grid"><div className="metric-card"><span>Potential overcharge</span><strong>{result.state === "needs_review" ? "Unresolved" : fmt(result.case!.totalPotentialOvercharge)}</strong><small>{result.state === "needs_review" ? "No claim amount assessed" : "Synthetic calculation: 400 × ₹45 or zero"}</small></div><div className="metric-card"><span>Invoices in scenario</span><strong>1</strong><small>INV-104 fixture</small></div><div className="metric-card"><span>Outcome</span><strong>{result.state === "needs_review" ? "Manual review" : result.case!.totalPotentialOvercharge ? "Review finding" : "No discrepancy"}</strong><small>Illustrative only</small></div></div>
