        {(["contract", "purchase_order", "invoice", "amendment"] as Kind[]).map(kind => { const entries = docs.filter(d => d.kind === kind); return <div className="doc-group" key={kind}><div className="group-title"><strong>{labels[kind]}{kind === "invoice" ? "s" : ""}</strong><span>{kind === "invoice" ? "Required · one or more" : kind === "amendment" ? "Optional · add any" : "Required · one"}</span></div>{entries.map((doc, index) => <article className="file-row" key={doc.key}><div className="pdf-icon">PDF</div><div className="file-main"><div className="file-line"><strong title={doc.file.name}>{doc.file.name}</strong><span>{formatSize(doc.file.size)}</span></div><label className="id-label">Printed document ID <input value={doc.id} onChange={e => update(doc.key, { id: e.target.value })} placeholder="Enter ID shown inside the PDF" aria-label={`${labels[kind]} ${index + 1} printed document ID`} /></label>{doc.progress > 0 && <div className="progress-track" aria-label={`Upload progress ${doc.progress}%`}><span style={{ width: `${doc.progress}%` }}/></div>}{doc.error && <p className="inline-error">{doc.error}</p>}</div><div className="row-actions"><button type="button" className="text-action" onClick={() => inputRefs.current[doc.key]?.click()}>Replace</button><input ref={node => { inputRefs.current[doc.key] = node; }} className="hidden-file" type="file" accept="application/pdf,.pdf" aria-label={`Replace ${doc.file.name}`} onChange={e => { replace(doc.key, e.target.files?.[0]); e.target.value = ""; }}/><button type="button" className="text-action remove" onClick={() => remove(doc.key)} aria-label={`Remove ${doc.file.name}`}>Remove</button></div></article>)}{(kind === "invoice" || kind === "amendment" || entries.length === 0) && addControl(kind)}</div>; })}
        <div className="identity-note"><span className="note-mark">i</span><span>Use the printed ID inside each document. MarginGhost keeps it as the source reference and checks that extracted facts reconcile to it. File names are never used as financial facts.</span></div>
        {!uniqueIds && <div className="error-box" role="alert"><strong>Document IDs must be unique</strong><p>Two or more documents have the same printed ID. Check the IDs shown inside the PDFs.</p></div>}
        {error && <div className="error-box" role="alert"><strong>Could not complete investigation</strong><p>{error}</p>{stage === "error" && <button className="text-action" onClick={investigate}>Retry intentionally →</button>}</div>}
        {demoInfo && <div className="demo-banner" role="status">{demoInfo}</div>}
        <div className="submit-row"><button className="primary-button" disabled={!ready || ["extracting", "investigating", "validating"].includes(stage)} onClick={investigate}>{["extracting", "investigating", "validating"].includes(stage) ? "Working…" : "Investigate documents"}<span aria-hidden="true">→</span></button><span className="submit-hint">Your PDFs and extracted text stay in this browser session.</span></div>
      </section>
      <aside className="side-column"><section className="card status-card"><div className="step">02 / INVESTIGATION</div><h2>Progress</h2><ol className="stage-list">{[["extracting", "Extracting PDFs"], ["investigating", "Investigating documents"], ["validating", "Validating evidence"], ["finished", "Finished"], ["review", "Needs review"]].map(([id, name]) => { const active = stage === id || (stage === "error" && id === "extracting"); const done = stage === "finished" || (stage === "review" && ["extracting", "investigating"].includes(id)) || (stage === "investigating" && id === "extracting") || (stage === "validating" && ["extracting", "investigating"].includes(id)); return <li key={id} className={`${active ? "active" : ""} ${done ? "done" : ""}`}><span className="stage-mark">{done ? "✓" : active ? <span className="spinner"/> : ""}</span>{name}{active && <small>{progress}</small>}</li>; })}</ol><div className="server-note">Steps appear as the server responds. Extraction and evidence checks are not assumed complete in advance.</div></section>
        <section className="card demo-card"><div className="step">LOCAL SYNTHETIC DEMONSTRATION</div><h2>Try a sample case</h2><p>Load provided synthetic PDFs. An investigation result is produced only if you submit them to the API.</p><div className="demo-actions"><button onClick={() => loadDemo("overcharge")}>Overcharge</button><button onClick={() => loadDemo("review")}>Needs review</button><button onClick={() => loadDemo("revised")}>Revised PO · zero</button></div><div className="demo-foot">No model claim is made until an actual request returns.</div></section></aside>
    </div>
    {result && <section className="results" aria-live="polite"><div className={`result-banner ${result.state === "needs_review" ? "review-banner" : "complete-banner"}`}><div><div className="step">INVESTIGATION RESULT</div><h2>{result.state === "needs_review" ? "Manual review needed" : "Investigation complete"}</h2><p>{result.state === "needs_review" ? (result.warnings[0] || "The documents could not be reconciled with enough confidence.") : result.case?.totalPotentialOvercharge === 0 ? "No potential overcharge was found in the invoices checked." : "Potential invoice overcharge identified. Review the cited source evidence before taking action."}</p></div><span className="status-chip">{result.state === "needs_review" ? "NEEDS REVIEW" : "COMPLETED"}</span></div>
      {result.state === "needs_review" && <div className="review-explainer"><strong>Do not treat this as a zero-overcharge result.</strong><span>The case could not be approved as a completed comparison. Resolve the warning or document identity issue and investigate again.</span></div>}
      {result.case && <><div className="metric-grid"><div className="metric-card"><span>Potential overcharge</span><strong>{fmt(result.case.totalPotentialOvercharge)}</strong><small>Calculated from checked invoice lines</small></div><div className="metric-card"><span>Invoices checked</span><strong>{result.case.checkedInvoices}</strong><small>Unique invoice records in this case</small></div><div className="metric-card"><span>Findings</span><strong>{result.case.findings.length}</strong><small>Potential discrepancies requiring review</small></div></div>
      <div className="card findings-card"><div className="section-head"><div><div className="step">LINE ITEM REVIEW</div><h2>Price comparisons</h2></div><span className="quiet-pill">All amounts INR</span></div>{result.case.findings.length === 0 ? <div className="zero-findings"><span className="zero-check">✓</span><div><strong>No findings in checked lines</strong><p>The completed case found no potential overcharge for the supplied documents.</p></div></div> : result.case.findings.map((f, i) => <article className="finding-row" key={`${f.invoiceId}-${f.sku}-${i}`}><div className="finding-head"><strong>{f.invoiceId} <span>·</span> {f.sku}</strong><span className={f.status === "needs_review" ? "finding-tag review-tag" : "finding-tag"}>{f.status === "needs_review" ? "REVIEW" : "POTENTIAL OVERCHARGE"}</span></div><p>{f.reason}</p><div className="comparison"><div><small>Contract unit price</small><strong>{f.expectedUnitPrice === undefined ? "Not established" : `${fmt(f.expectedUnitPrice)} / unit`}</strong></div><b aria-hidden="true">→</b><div><small>PO unit price</small><strong>{f.status === "potential_overcharge" && f.expectedUnitPrice !== undefined ? `${fmt(f.expectedUnitPrice)} / unit` : "Review source evidence"}</strong></div><b aria-hidden="true">→</b><div><small>Invoice unit price</small><strong>{fmt(f.billedUnitPrice)} / unit</strong></div><div><small>Quantity</small><strong>{f.quantity.toLocaleString("en-IN")}</strong></div><div className="line-total"><small>Potential line amount</small><strong>{f.potentialOvercharge === undefined ? "Review required" : fmt(f.potentialOvercharge)}</strong></div></div></article>)}</div></>}
      {(result.warnings.length > 0 || result.diagnostic) && <div className="warnings-box"><strong>Warnings and review notes</strong>{result.warnings.map((w, i) => <p key={i}>{w}</p>)}{result.diagnostic && <p>Diagnostic: {result.diagnostic.category}{result.diagnostic.status ? ` (HTTP ${result.diagnostic.status})` : ""}{result.diagnostic.fields?.length ? ` · Fields: ${result.diagnostic.fields.join(", ")}` : ""}</p>}</div>}
      <section className="card evidence-card"><div className="section-head"><div><div className="step">SOURCE TRAIL</div><h2>Evidence</h2><p>Exact excerpts from uploaded page text. Evidence is shown as source material, not generated proof.</p></div><label className="search-box"><span>⌕</span><input value={filter} onChange={e => setFilter(e.target.value)} placeholder="Filter evidence" aria-label="Filter evidence"/></label></div>{filteredEvidence.length === 0 ? <p className="empty-evidence">No evidence matches this filter.</p> : <div className="evidence-list">{filteredEvidence.map((e, i) => <article className="evidence-item" key={`${e.sourceId}-${e.page}-${e.field}-${i}`}><div className="evidence-meta"><span className="source-id">{e.sourceId}</span><span>PAGE {e.page}</span><span>{e.field.replaceAll(".", " / ").replaceAll("[", " ").replaceAll("]", "")}</span></div><blockquote>“{e.excerpt}”</blockquote></article>)}</div>}</section>
      <p className="disclaimer">Potential discrepancy only. MarginGhost does not approve a claim, contact suppliers or change payments.</p>
    </section>}
    <footer><span>MarginGhost <small>V0.4</small></span><span>Evidence first. Human reviewed.</span></footer>
  </main>;
}
:root{color-scheme:light;--paper:#f6f5f0;--white:#fff;--ink:#242923;--muted:#74796f;--line:#e3e2db;--green:#315f49;--amber:#8b5c16;font-family:Arial,Helvetica,sans-serif;background:var(--paper);color:var(--ink)}*{box-sizing:border-box}body{margin:0}button,input{font:inherit}button{cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid #80a88d;outline-offset:2px}.shell{max-width:1200px;margin:auto;padding:0 34px}.topbar{height:76px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:11px;color:var(--ink);text-decoration:none;font-size:17px;font-weight:800;letter-spacing:-.6px}.brand small,footer small{font:500 10px monospace;color:#888c82;margin-left:3px}.brand-icon{height:29px;width:29px;background:var(--green);color:white;border-radius:7px;display:grid;place-items:center}.top-note,.step,.eyebrow,.group-title span,.evidence-meta,.demo-foot,.status-chip{font-family:monospace;letter-spacing:.035em}.top-note{font-size:10px;color:#888c82}.intro{padding:47px 0 31px;max-width:750px}.eyebrow{color:var(--green);font-size:10px;display:flex;align-items:center;gap:8px}.dot{height:7px;width:7px;border-radius:50%;background:#679077}.intro h1{font-size:clamp(34px,4vw,49px);line-height:1.11;letter-spacing:-2.2px;max-width:690px;margin:16px 0 13px}.intro p,.section-copy,.demo-card>p{color:var(--muted);font-size:14px;line-height:1.65;margin:0;max-width:670px}.workspace{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(280px,.85fr);gap:18px;align-items:start}.card{background:var(--white);border:1px solid var(--line);border-radius:10px}.upload-card{padding:23px 24px}.section-head{display:flex;align-items:flex-start;justify-content:space-between;gap:14px}.step{font-size:9px;color:#85897f}.section-head h2,.status-card h2,.demo-card h2,.evidence-card h2{font-size:19px;margin:5px 0 0}.quiet-pill{border:1px solid var(--line);border-radius:20px;padding:6px 9px;font:10px monospace;color:#686d64;white-space:nowrap}.section-copy{font-size:12px;margin:9px 0 22px}.doc-group{margin-top:16px}.group-title{display:flex;align-items:baseline;justify-content:space-between;padding-bottom:8px;border-bottom:1px solid var(--line)}.group-title strong{font-size:12px}.group-title span{font-size:9px;color:#8b8f85}.file-row{display:flex;gap:11px;align-items:flex-start;padding:11px 0;border-bottom:1px solid #efeee9}.pdf-icon{flex:none;height:29px;width:29px;display:grid;place-items:center;border-radius:5px;background:#f8eeeb;color:#a34b3d;font:9px monospace}.file-main{min-width:0;flex:1}.file-line{display:flex;align-items:center;gap:10px}.file-line strong{font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:300px}.file-line span{font:9px monospace;color:#999b94;white-space:nowrap}.id-label{display:flex;align-items:center;gap:8px;margin-top:8px;color:#777c73;font-size:10px}.id-label input{width:210px;max-width:65%;padding:5px 7px;border:1px solid #e4e3dc;border-radius:4px;font-size:10px;background:#fdfdfb}.row-actions{display:flex;gap:9px;padding-top:2px;white-space:nowrap}.text-action{border:0;background:none;padding:3px 0;color:var(--green);font-size:10px;font-weight:600}.text-action:hover{text-decoration:underline}.text-action.remove{color:#85877f}.hidden-file,.add-button input{position:absolute;clip:rect(0,0,0,0);height:1px;width:1px;overflow:hidden}.add-button{display:inline-flex;align-items:center;gap:5px;margin:9px 0 3px;border:1px solid #e1e3dc;border-radius:5px;padding:7px 9px;color:#56695b;font-size:10px;font-weight:600;cursor:pointer;background:#fff}.add-button:hover{background:#f7faf7}.progress-track{height:2px;background:#e8eee8;margin-top:8px;border-radius:2px;overflow:hidden}.progress-track span{display:block;height:100%;background:var(--green)}.identity-note{display:flex;align-items:flex-start;gap:9px;margin:20px 0 0;padding:11px 12px;background:#f8f8f4;border:1px solid #efeee8;border-radius:6px;color:#747970;font-size:10px;line-height:1.55}.note-mark{width:15px;height:15px;flex:none;border:1px solid #aaa99e;border-radius:50%;display:grid;place-items:center}.submit-row{margin-top:16px;display:flex;align-items:center;gap:12px}.primary-button{height:39px;padding:0 15px;border:0;border-radius:5px;background:var(--green);color:white;font-size:11px;font-weight:700;display:flex;align-items:center;gap:19px}.primary-button:disabled{opacity:.43;cursor:not-allowed}.submit-hint{font-size:9px;color:#898d83}.error-box,.warnings-box{margin-top:13px;border:1px solid #ead3cf;background:#fff8f7;padding:11px 12px;border-radius:6px;color:#803f39;font-size:11px}.error-box p,.warnings-box p{margin:5px 0 0;line-height:1.5}.demo-banner{margin-top:12px;padding:10px;background:#f2f5ee;border:1px solid #dfe7da;border-radius:5px;color:#52664d;font-size:10px;line-height:1.5}.side-column{display:grid;gap:14px}.status-card,.demo-card{padding:20px}.status-card h2,.demo-card h2{font-size:17px}.stage-list{list-style:none;padding:0;margin:17px 0 0}.stage-list li{position:relative;display:grid;grid-template-columns:19px 1fr;align-items:center;column-gap:8px;padding:0 0 17px;font-size:11px;color:#91948b}.stage-list li:not(:last-child):after{content:"";position:absolute;left:8px;top:17px;bottom:0;width:1px;background:#e9e8e1}.stage-list li.active{color:#2e5942;font-weight:600}.stage-list li.done{color:#58685a}.stage-mark{position:relative;z-index:1;width:17px;height:17px;border:1px solid #deded5;background:#fff;border-radius:50%;display:grid;place-items:center;color:var(--green);font:10px monospace}.stage-list li small{grid-column:2;font-weight:400;font-size:9px;color:#878c82;margin-top:4px}.spinner{height:7px;width:7px;border:1px solid #a2b5a5;border-top-color:#315f49;border-radius:50%;animation:spin .8s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.server-note{border-top:1px solid #efeee8;padding-top:11px;font-size:9px;line-height:1.55;color:#8a8e84}.demo-card{background:#faf9f5}.demo-card>p{font-size:11px;margin:8px 0 13px}.demo-actions{display:grid;gap:6px}.demo-actions button{background:white;border:1px solid var(--line);border-radius:4px;text-align:left;padding:8px 9px;font-size:10px;color:#465447}.demo-foot{font-size:8px;color:#989990;margin-top:10px;line-height:1.5}.results{margin-top:20px}.result-banner{display:flex;justify-content:space-between;align-items:flex-start;gap:15px;padding:20px 22px;border:1px solid;border-radius:8px}.complete-banner{background:#f1f6f1;border-color:#d9e6d9}.review-banner{background:#fff8eb;border-color:#eddfbd}.result-banner h2{font-size:21px;margin:5px 0}.result-banner p{font-size:11px;color:#687267;line-height:1.5;margin:0}.status-chip{font-size:8px;white-space:nowrap;border-radius:3px;padding:6px 8px;background:#fff9;border:1px solid #d6ddd3;color:#4d6b53}.review-banner .status-chip{color:#80591e;border-color:#e8d7ae}.review-explainer{display:grid;gap:5px;padding:12px 14px;background:#fff5e2;border:1px solid #ead8b4;border-top:0;color:#76561f;font-size:11px}.review-explainer span{color:#816f4e;line-height:1.5}.metric-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:11px;margin:13px 0}.metric-card{background:#fff;border:1px solid var(--line);border-radius:7px;padding:14px 15px}.metric-card span,.metric-card small{display:block;color:#81857b;font-size:9px}.metric-card strong{display:block;font-size:24px;letter-spacing:-.7px;margin:8px 0 3px}.metric-card small{font-size:8px}.findings-card{padding:20px 22px;margin-top:13px}.finding-row{padding:16px 0 5px;border-top:1px solid #ecebe5;margin-top:14px}.finding-head{display:flex;justify-content:space-between;gap:12px;align-items:center}.finding-head>strong{font-size:12px}.finding-head>strong span{color:#aaa}.finding-tag{font:8px monospace;color:#8a5d22;background:#faf1df;padding:5px 7px;border-radius:3px}.review-tag{color:#8f463f;background:#f9eae7}.finding-row>p{font-size:10px;color:#73776e;margin:8px 0 12px;line-height:1.5}.comparison{display:grid;grid-template-columns:1fr 17px 1fr 75px 1fr;gap:8px;align-items:center;background:#f8f8f5;border:1px solid #efeee8;border-radius:5px;padding:10px}.comparison>div{min-width:0}.comparison small{display:block;color:#8b8e85;font-size:8px;margin-bottom:5px}.comparison strong{font-size:10px}.comparison>b{text-align:center;color:#a3a59c;font-size:11px}.zero-findings{display:flex;gap:11px;align-items:center;padding:18px 0 2px;border-top:1px solid #ecebe5;margin-top:14px}.zero-check{height:24px;width:24px;border-radius:50%;display:grid;place-items:center;background:#eaf2e9;color:#456f4e}.zero-findings strong{font-size:11px}.zero-findings p{margin:4px 0 0;font-size:10px;color:#7d8178}.evidence-card{padding:20px 22px;margin-top:13px}.evidence-card .section-head{align-items:center}.evidence-card .section-head p{margin:5px 0 0;color:#85897f;font-size:9px}.search-box{height:30px;display:flex;align-items:center;gap:5px;border:1px solid var(--line);border-radius:4px;padding:0 8px;color:#7f8379}.search-box input{border:0;outline:0;width:120px;font-size:9px;background:transparent}.evidence-list{margin-top:14px;border-top:1px solid #ecebe5}.evidence-item{padding:12px 0;border-bottom:1px solid #efeee9}.evidence-meta{display:flex;gap:12px;align-items:center;color:#92958c;font-size:8px}.evidence-meta .source-id{font-weight:500;color:#45654d}.evidence-item blockquote{margin:7px 0 0;color:#454a43;font:11px/1.65 monospace}.empty-evidence{font-size:11px;color:#868a81}.disclaimer{text-align:center;color:#93968d;font-size:9px;padding:13px 0 8px}footer{display:flex;justify-content:space-between;padding:24px 0 30px;border-top:1px solid var(--line);color:#888c82;font-size:9px}footer>span:first-child{font-weight:700;color:#565b53}.inline-error{margin:6px 0 0;color:#9c4039;font-size:9px}
@media(max-width:800px){.shell{padding:0 20px}.workspace{grid-template-columns:1fr}.side-column{grid-template-columns:1fr 1fr}.demo-actions{grid-template-columns:1fr}.intro{padding-top:37px}.upload-card{padding:20px}.comparison{grid-template-columns:1fr 12px 1fr 12px 1fr 60px 1fr}}
@media(max-width:560px){.shell{padding:0 14px}.topbar{height:62px}.top-note{font-size:8px}.intro{padding:34px 0 24px}.intro h1{font-size:35px;letter-spacing:-1.6px}.intro p{font-size:12px}.upload-card,.status-card,.demo-card,.findings-card,.evidence-card{padding:16px}.section-head{flex-wrap:wrap}.section-head h2{font-size:17px}.group-title span{font-size:8px}.file-row{gap:8px}.file-line strong{max-width:175px}.row-actions{gap:7px}.text-action{font-size:9px}.id-label{align-items:flex-start;flex-direction:column;gap:4px}.id-label input{max-width:100%;width:100%}.submit-row{align-items:flex-start;flex-direction:column}.submit-hint{line-height:1.5}.side-column{grid-template-columns:1fr}.demo-actions{grid-template-columns:1fr 1fr}.demo-actions button:last-child{grid-column:1/-1}.metric-grid{grid-template-columns:1fr;gap:7px}.metric-card{padding:11px 13px}.metric-card strong{font-size:21px;margin:4px 0}.result-banner{padding:15px}.result-banner h2{font-size:18px}.comparison{grid-template-columns:1fr 1fr;gap:9px}.comparison>b{display:none}.comparison>div:nth-of-type(3){grid-column:auto}.comparison .line-total{grid-column:auto}.finding-head{align-items:flex-start;flex-direction:column;gap:7px}.evidence-card .section-head{align-items:flex-start}.search-box{width:100%}.search-box input{width:100%}footer{font-size:8px}}
