@media(max-width:560px){.shell{padding:0 14px}.topbar{height:62px}.top-note{font-size:8px}.intro{padding:34px 0 24px}.intro h1{font-size:35px;letter-spacing:-1.6px}.intro p{font-size:12px}.upload-card,.status-card,.demo-card,.findings-card,.evidence-card{padding:16px}.section-head{flex-wrap:wrap}.section-head h2{font-size:17px}.group-title span{font-size:8px}.file-row{gap:8px}.file-line strong{max-width:175px}.row-actions{gap:7px}.text-action{font-size:9px}.id-label{align-items:flex-start;flex-direction:column;gap:4px}.id-label input{max-width:100%;width:100%}.submit-row{align-items:flex-start;flex-direction:column}.submit-hint{line-height:1.5}.side-column{grid-template-columns:1fr}.demo-actions{grid-template-columns:1fr 1fr}.demo-actions button:last-child{grid-column:1/-1}.metric-grid{grid-template-columns:1fr;gap:7px}.metric-card{padding:11px 13px}.metric-card strong{font-size:21px;margin:4px 0}.result-banner{padding:15px}.result-banner h2{font-size:18px}.comparison{grid-template-columns:1fr 1fr;gap:9px}.comparison>b{display:none}.comparison>div:nth-of-type(3){grid-column:auto}.comparison .line-total{grid-column:auto}.finding-head{align-items:flex-start;flex-direction:column;gap:7px}.evidence-card .section-head{align-items:flex-start}.search-box{width:100%}.search-box input{width:100%}footer{font-size:8px}}
